// このロジックは src/normalize.js と同一内容を手動で複製している（n8n Codeノードは
// 外部モジュールをimportできないため）。変更時は両方を同期させること。

const TRACKING_PARAMS = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content', 'fbclid', 'gclid', 'ref'];

// http(s) URLのみを対象とする単純なパーサー。
// 注意：n8nのCodeノードのサンドボックス（JS Task Runner）にはグローバルの`URL`/
// `URLSearchParams`が存在せず、`require('url')`も許可されていないため、標準の
// `URL`クラスを一切使わずに正規表現と文字列操作のみで実装している。
const ABSOLUTE_HTTP_URL_PATTERN = /^(https?):\/\/([^/?#:]+)(?::(\d+))?([^?#]*)(?:\?([^#]*))?(?:#.*)?$/i;

function parseHttpUrl(rawUrl) {
  if (!rawUrl || typeof rawUrl !== 'string') return null;
  const match = ABSOLUTE_HTTP_URL_PATTERN.exec(rawUrl.trim());
  if (!match) return null;
  const [, protocol, hostname, port, path, query] = match;
  return { protocol: protocol.toLowerCase(), hostname, port: port || '', pathname: path || '', query: query || '' };
}

function decodeQueryKey(rawKey) {
  try {
    return decodeURIComponent(rawKey.replace(/\+/g, ' '));
  } catch (e) {
    return rawKey;
  }
}

function normalizeUrl(rawUrl) {
  const parsed = parseHttpUrl(rawUrl);
  if (!parsed) return null;

  const hostname = parsed.hostname.toLowerCase();
  const port = (parsed.protocol === 'http' && parsed.port === '80') || (parsed.protocol === 'https' && parsed.port === '443')
    ? ''
    : parsed.port;

  let pathname = parsed.pathname || '/';
  if (!pathname.startsWith('/')) pathname = `/${pathname}`;
  if (pathname.length > 1 && pathname.endsWith('/')) pathname = pathname.slice(0, -1);

  const params = [];
  for (const pair of parsed.query ? parsed.query.split('&') : []) {
    if (!pair) continue;
    const eqIdx = pair.indexOf('=');
    const rawKey = eqIdx === -1 ? pair : pair.slice(0, eqIdx);
    const rawValue = eqIdx === -1 ? '' : pair.slice(eqIdx + 1);
    if (TRACKING_PARAMS.includes(decodeQueryKey(rawKey))) continue;
    params.push([rawKey, rawValue]);
  }
  params.sort((a, b) => {
    const ka = decodeQueryKey(a[0]);
    const kb = decodeQueryKey(b[0]);
    return ka < kb ? -1 : ka > kb ? 1 : 0;
  });
  const query = params.map(([k, v]) => (v ? `${k}=${v}` : k)).join('&');

  return `${parsed.protocol}://${hostname}${port ? `:${port}` : ''}${pathname}${query ? `?${query}` : ''}`;
}

function getHostname(rawUrl) {
  const parsed = parseHttpUrl(rawUrl);
  return parsed ? parsed.hostname.toLowerCase() : null;
}

function classifySourceType(url, officialUrl) {
  const h1 = getHostname(url);
  const h2 = getHostname(officialUrl);
  if (!h1 || !h2) return 'external';
  return h1 === h2 ? 'official' : 'external';
}

function dedupeSources(rawSources) {
  const map = new Map();
  const order = [];
  let counter = 0;
  for (const s of rawSources) {
    const normalized = normalizeUrl(s.url);
    if (!normalized) continue;
    if (!map.has(normalized)) {
      counter += 1;
      map.set(normalized, {
        id: 'src' + counter,
        url: s.url,
        normalized_url: normalized,
        title: s.title || null,
        snippet: s.snippet || null,
        source_type: s.source_type,
        origin: [s.origin],
      });
      order.push(normalized);
    } else {
      const entry = map.get(normalized);
      if (!entry.title && s.title) entry.title = s.title;
      if (!entry.snippet && s.snippet) entry.snippet = s.snippet;
      if (!entry.origin.includes(s.origin)) entry.origin.push(s.origin);
    }
  }
  return order.map((k) => map.get(k));
}

function extractErrorMessage(err) {
  if (typeof err === 'string') return err;
  if (err && typeof err === 'object') return err.message || JSON.stringify(err);
  return 'unknown error';
}

function buildSearchSummary(searchItem, query, maxResults) {
  if (searchItem && searchItem.error) {
    return { status: 'error', query, max_results: maxResults, returned_count: 0, error_message: extractErrorMessage(searchItem.error) };
  }
  const results = Array.isArray(searchItem && searchItem.results) ? searchItem.results : [];
  if (results.length === 0) {
    return { status: 'empty', query, max_results: maxResults, returned_count: 0 };
  }
  return { status: 'ok', query, max_results: maxResults, returned_count: results.length };
}

function buildExtractSummary(extractItem, requestedUrl) {
  if (extractItem && extractItem.error) {
    return { status: 'error', requested_url: requestedUrl, error_message: extractErrorMessage(extractItem.error), failed_urls: [] };
  }
  const failed = Array.isArray(extractItem && extractItem.failed_results) ? extractItem.failed_results : [];
  if (failed.length > 0) {
    return {
      status: 'error',
      requested_url: requestedUrl,
      error_message: failed.map((f) => f.url + ': ' + f.error).join('; '),
      failed_urls: failed.map((f) => f.url),
    };
  }
  const results = Array.isArray(extractItem && extractItem.results) ? extractItem.results : [];
  if (results.length === 0) {
    return { status: 'empty', requested_url: requestedUrl, failed_urls: [] };
  }
  return { status: 'ok', requested_url: requestedUrl, failed_urls: [] };
}

function buildResearchOutput({ input, searchItem, extractItem }) {
  const query = input.company_name + ' 会社概要 最新ニュース';
  const maxResults = 3;
  const search = buildSearchSummary(searchItem, query, maxResults);
  const extract = buildExtractSummary(extractItem, input.official_url);

  const rawSources = [];

  if (extract.status === 'ok') {
    for (const r of extractItem.results) {
      rawSources.push({
        url: r.url,
        title: null,
        snippet: r.raw_content ? String(r.raw_content).slice(0, 500) : null,
        source_type: classifySourceType(r.url, input.official_url),
        origin: 'extract',
      });
    }
  }

  if (search.status === 'ok') {
    for (const r of searchItem.results) {
      rawSources.push({
        url: r.url,
        title: r.title || null,
        snippet: r.content || null,
        source_type: classifySourceType(r.url, input.official_url),
        origin: 'search',
      });
    }
  }

  const sources = dedupeSources(rawSources);

  const warnings = [];
  if (search.status === 'error') warnings.push('Tavily Search呼び出しに失敗しました: ' + search.error_message);
  if (search.status === 'empty') warnings.push('Tavily Searchの結果が0件でした。');
  if (extract.status === 'error') warnings.push('Tavily Extractに失敗しました: ' + extract.error_message);
  if (sources.length === 0) warnings.push('有効な出典が1件も取得できませんでした。');

  return {
    input,
    search,
    extract,
    sources,
    warnings,
    generated_at: new Date().toISOString(),
  };
}

const input = $('Fixed Test Input').first().json;
const searchItem = $('Tavily Search').first().json;
const extractItem = $('Tavily Extract').first().json;

return [{ json: buildResearchOutput({ input, searchItem, extractItem }) }];

// このロジックは src/openai_request.js と同一内容を手動で複製している（n8n Codeノードは
// 外部モジュールをimportできないため）。変更時は両方を同期させること。

const OPENAI_MODEL = 'gpt-5.6-terra';
const OPENAI_REASONING_EFFORT = 'low';
const OPENAI_MAX_OUTPUT_TOKENS = 4000;

const PHASE4_SCHEMA = {
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Phase4LlmAnalysisOutput",
  "description": "OpenAI Responses API（text.format: json_schema, strict: true）へ送信するLLM生成部分のみのSchema。company_name/official_url/sourcesはPhase3の確定情報をそのまま使うためLLMには生成させない。事実(business_overview/recent_news/org_signals)はsource_ids、仮説(proposal_hypotheses)はevidence_source_idsをそれぞれminItems:1で必須とする。取得できない最近の動きはrecent_newsに含めずuncertaintiesへ記録する（プロンプト指示）。全objectはadditionalProperties:falseとし、定義した全プロパティをrequiredにする。",
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "company_profile": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "business_overview": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "text": { "type": "string" },
            "source_ids": {
              "type": "array",
              "minItems": 1,
              "items": { "type": "string" }
            }
          },
          "required": ["text", "source_ids"]
        },
        "recent_news": {
          "type": "array",
          "description": "出典から裏付けが取れる最近の動きのみ。無ければ空配列にし、uncertaintiesへ理由を記録する。",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "summary": { "type": "string" },
              "source_ids": {
                "type": "array",
                "minItems": 1,
                "items": { "type": "string" }
              }
            },
            "required": ["summary", "source_ids"]
          }
        },
        "org_signals": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "signal": { "type": "string" },
              "source_ids": {
                "type": "array",
                "minItems": 1,
                "items": { "type": "string" }
              }
            },
            "required": ["signal", "source_ids"]
          }
        }
      },
      "required": ["business_overview", "recent_news", "org_signals"]
    },
    "proposal_hypotheses": {
      "type": "array",
      "description": "offering（提案する商品・サービス）との適合理由をrationaleに含める。",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "hypothesis": { "type": "string" },
          "rationale": { "type": "string" },
          "evidence_source_ids": {
            "type": "array",
            "minItems": 1,
            "items": { "type": "string" }
          }
        },
        "required": ["hypothesis", "rationale", "evidence_source_ids"]
      }
    },
    "discovery_questions": {
      "type": "array",
      "description": "offeringを前提に商談で確認すべき質問。出典は不要。",
      "items": { "type": "string" }
    },
    "uncertainties": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "note": { "type": "string" },
          "reason": { "type": "string" }
        },
        "required": ["note", "reason"]
      }
    }
  },
  "required": ["company_profile", "proposal_hypotheses", "discovery_questions", "uncertainties"]
};

function formatSourceLine(source) {
  const title = source.title ? source.title : '(タイトルなし)';
  const snippet = source.snippet ? source.snippet : '(本文なし)';
  return `[${source.id}] (${source.source_type}) ${title}\nURL: ${source.url}\n${snippet}`;
}

function buildPromptText({ input, sources }) {
  const groundingLines = (sources ?? []).map(formatSourceLine).join('\n\n');

  return `あなたは営業担当者の商談準備を支援するリサーチアシスタントです。
以下の出典（Tavilyの検索・抽出結果）のみを根拠に、企業情報の分析を行ってください。
出典に無い情報を推測や一般知識で補ってはいけません。

# 調査対象
企業名: ${input.company_name}
公式URL: ${input.official_url}
調査目的: ${input.research_purpose}

# 提案する商品・サービス（offering）
${input.offering}

# 出典一覧
${groundingLines || '(出典なし)'}

# 指示
- business_overview / recent_news / org_signals の各項目には、根拠となった出典のidを source_ids に必ず1件以上含めてください。
- 出典から裏付けが取れない「最近の動き」は recent_news に含めず、uncertainties に理由とともに記録してください。
- proposal_hypotheses は、上記offeringとの適合理由を rationale に含め、evidence_source_ids に根拠となる出典idを1件以上含めてください。
- discovery_questions は、offeringを前提に、商談で確認すべき質問にしてください。出典は不要です。
- 出典が無い、または情報が不足している場合は uncertainties に記録してください。`;
}

function buildOpenAiRequestBody({ input, sources }) {
  return {
    model: OPENAI_MODEL,
    reasoning: { effort: OPENAI_REASONING_EFFORT },
    max_output_tokens: OPENAI_MAX_OUTPUT_TOKENS,
    input: buildPromptText({ input, sources }),
    text: {
      format: {
        type: 'json_schema',
        name: 'phase4_llm_analysis_output',
        strict: true,
        schema: PHASE4_SCHEMA,
      },
    },
  };
}

const input = $('Fixed Test Input').first().json;
const tavilyOutput = $('Normalize, Dedupe & Structure Output').first().json;

return [{ json: buildOpenAiRequestBody({ input, sources: tavilyOutput.sources }) }];

// このロジックは src/assemble_report.js・src/render_markdown.js と同一内容を手動で
// 複製している（n8n Codeノードは外部モジュール（ajv等）をimportできないため）。
// 変更時は両方（3ファイル）を同期させること。Phase4のLLM出力Schema検証はajv等の
// ライブラリを使わず、手書きの構造チェックのみで行う（Phase3のnormalize.jsと同じ方針）。

const OPENAI_MODEL = 'gpt-5.6-terra';

function isNonEmptyStringArray(value) {
  return Array.isArray(value) && value.length > 0 && value.every((v) => typeof v === 'string');
}

function hasExactKeys(obj, keys) {
  if (typeof obj !== 'object' || obj === null || Array.isArray(obj)) return false;
  const objKeys = Object.keys(obj);
  if (objKeys.length !== keys.length) return false;
  return keys.every((k) => objKeys.includes(k));
}

function validatePhase4Schema(analysis) {
  const errors = [];
  const fail = (msg) => errors.push(msg);

  if (!hasExactKeys(analysis, ['company_profile', 'proposal_hypotheses', 'discovery_questions', 'uncertainties'])) {
    fail('root: company_profile/proposal_hypotheses/discovery_questions/uncertaintiesが過不足なく必要です');
    return { valid: false, errors };
  }

  const cp = analysis.company_profile;
  if (!hasExactKeys(cp, ['business_overview', 'recent_news', 'org_signals'])) {
    fail('company_profile: business_overview/recent_news/org_signalsが過不足なく必要です');
  } else {
    const bo = cp.business_overview;
    if (!hasExactKeys(bo, ['text', 'source_ids']) || typeof bo.text !== 'string' || !isNonEmptyStringArray(bo.source_ids)) {
      fail('company_profile.business_overview: text(string)とsource_ids(1件以上のstring配列)が必要です');
    }

    if (!Array.isArray(cp.recent_news)) {
      fail('company_profile.recent_news: 配列である必要があります');
    } else {
      cp.recent_news.forEach((item, i) => {
        if (
          !hasExactKeys(item, ['summary', 'source_ids']) ||
          typeof item.summary !== 'string' ||
          !isNonEmptyStringArray(item.source_ids)
        ) {
          fail(`company_profile.recent_news[${i}]: summary(string)とsource_ids(1件以上のstring配列)が必要です`);
        }
      });
    }

    if (!Array.isArray(cp.org_signals)) {
      fail('company_profile.org_signals: 配列である必要があります');
    } else {
      cp.org_signals.forEach((item, i) => {
        if (
          !hasExactKeys(item, ['signal', 'source_ids']) ||
          typeof item.signal !== 'string' ||
          !isNonEmptyStringArray(item.source_ids)
        ) {
          fail(`company_profile.org_signals[${i}]: signal(string)とsource_ids(1件以上のstring配列)が必要です`);
        }
      });
    }
  }

  if (!Array.isArray(analysis.proposal_hypotheses)) {
    fail('proposal_hypotheses: 配列である必要があります');
  } else {
    analysis.proposal_hypotheses.forEach((item, i) => {
      if (
        !hasExactKeys(item, ['hypothesis', 'rationale', 'evidence_source_ids']) ||
        typeof item.hypothesis !== 'string' ||
        typeof item.rationale !== 'string' ||
        !isNonEmptyStringArray(item.evidence_source_ids)
      ) {
        fail(`proposal_hypotheses[${i}]: hypothesis/rationale(string)とevidence_source_ids(1件以上のstring配列)が必要です`);
      }
    });
  }

  if (!Array.isArray(analysis.discovery_questions) || !analysis.discovery_questions.every((q) => typeof q === 'string')) {
    fail('discovery_questions: string配列である必要があります');
  }

  if (!Array.isArray(analysis.uncertainties)) {
    fail('uncertainties: 配列である必要があります');
  } else {
    analysis.uncertainties.forEach((item, i) => {
      if (!hasExactKeys(item, ['note', 'reason']) || typeof item.note !== 'string' || typeof item.reason !== 'string') {
        fail(`uncertainties[${i}]: note/reason(string)が必要です`);
      }
    });
  }

  return { valid: errors.length === 0, errors };
}

function collectSourceIdRefs(analysis) {
  const refs = [];
  const pushRefs = (ids, refPath) => {
    if (!Array.isArray(ids)) return;
    for (const id of ids) refs.push({ id, path: refPath });
  };

  const overview = analysis?.company_profile?.business_overview;
  if (overview) pushRefs(overview.source_ids, 'company_profile.business_overview.source_ids');

  (analysis?.company_profile?.recent_news ?? []).forEach((item, i) => {
    pushRefs(item.source_ids, `company_profile.recent_news[${i}].source_ids`);
  });

  (analysis?.company_profile?.org_signals ?? []).forEach((item, i) => {
    pushRefs(item.source_ids, `company_profile.org_signals[${i}].source_ids`);
  });

  (analysis?.proposal_hypotheses ?? []).forEach((item, i) => {
    pushRefs(item.evidence_source_ids, `proposal_hypotheses[${i}].evidence_source_ids`);
  });

  return refs;
}

function validateAnalysis(analysis, sourceIds) {
  if (typeof analysis !== 'object' || analysis === null || Array.isArray(analysis)) {
    return { valid: false, status: 'invalid_schema', detail: 'LLM出力がオブジェクトではありません' };
  }

  const schemaResult = validatePhase4Schema(analysis);
  if (!schemaResult.valid) {
    return { valid: false, status: 'invalid_schema', detail: schemaResult.errors.join(' / ') };
  }

  const knownIds = new Set(sourceIds);
  const invalidRefs = collectSourceIdRefs(analysis).filter((ref) => !knownIds.has(ref.id));
  if (invalidRefs.length > 0) {
    const detail = invalidRefs.map((r) => `${r.path}: "${r.id}"`).join(', ');
    return { valid: false, status: 'invalid_reference', detail: `存在しないsource idを参照しています: ${detail}` };
  }

  return { valid: true };
}

function classifyResponse(response) {
  if (!response || typeof response !== 'object') {
    return { status: 'empty', detail: 'レスポンスが空、または不正な形式です' };
  }

  if (response.error) {
    const message = typeof response.error === 'string' ? response.error : response.error.message;
    return { status: 'error', detail: message ?? 'OpenAI APIがエラーを返しました' };
  }

  if (response.status === 'failed') {
    return { status: 'error', detail: response.error?.message ?? 'OpenAIの応答status=failed' };
  }

  if (response.status === 'incomplete') {
    return {
      status: 'incomplete',
      detail: response.incomplete_details?.reason ?? 'OpenAIの応答が不完全でした（理由不明）',
    };
  }

  if (response.status !== 'completed') {
    return { status: 'empty', detail: `想定外のstatusです: ${response.status}` };
  }

  const messageItem = (response.output ?? []).find((o) => o.type === 'message');
  const contentItems = messageItem?.content ?? [];

  const refusal = contentItems.find((c) => c.type === 'refusal');
  if (refusal) {
    return { status: 'refusal', detail: refusal.refusal ?? 'OpenAIがリクエストを拒否しました' };
  }

  const textItem = contentItems.find((c) => c.type === 'output_text');
  const text = textItem?.text;
  if (!text || text.trim() === '') {
    return { status: 'empty', detail: '出力テキストが空でした' };
  }

  let parsed;
  try {
    parsed = JSON.parse(text);
  } catch (e) {
    return { status: 'invalid_schema', detail: `JSONとして解析できませんでした: ${e.message}` };
  }

  return { status: 'ok', analysis: parsed };
}

function assembleReport({ input, tavilyOutput, openAiResponse }) {
  const sources = tavilyOutput?.sources ?? [];
  const sourceIds = sources.map((s) => s.id);

  const classification = classifyResponse(openAiResponse);

  let llmStatus = classification.status;
  let llmDetail = classification.detail ?? null;
  let report = null;

  if (classification.status === 'ok') {
    const validation = validateAnalysis(classification.analysis, sourceIds);
    if (!validation.valid) {
      llmStatus = validation.status;
      llmDetail = validation.detail;
    } else {
      const analysis = classification.analysis;
      report = {
        sources,
        company_profile: {
          company_name: input.company_name,
          official_url: input.official_url,
          business_overview: analysis.company_profile.business_overview,
          recent_news: analysis.company_profile.recent_news,
          org_signals: analysis.company_profile.org_signals,
        },
        proposal_hypotheses: analysis.proposal_hypotheses,
        discovery_questions: analysis.discovery_questions,
        uncertainties: analysis.uncertainties,
      };
    }
  }

  return {
    meta: {
      input,
      generated_at: new Date().toISOString(),
      tavily: {
        search: tavilyOutput?.search ?? null,
        extract: tavilyOutput?.extract ?? null,
        warnings: tavilyOutput?.warnings ?? [],
      },
      llm: {
        status: llmStatus,
        model: OPENAI_MODEL,
        detail: llmDetail,
      },
    },
    report,
  };
}

function renderSourceRefs(ids) {
  if (!ids || ids.length === 0) return '';
  return ' ' + ids.map((id) => `[^${id}]`).join('');
}

function renderFailureMarkdown(meta) {
  const companyName = meta.input.company_name;
  return `# ${companyName} 商談準備レポート（生成失敗）

生成日時: ${meta.generated_at}

## 結果

OpenAIによる分析の生成に失敗しました。架空の情報で補うことは行っていません。

- 状態: \`${meta.llm.status}\`
- 詳細: ${meta.llm.detail ?? '(詳細不明)'}

Tavilyの調査結果自体は取得できています（下記参照）。再実行するか、
入力・出典の内容を確認してください。

- Search: ${meta.tavily.search?.status ?? '不明'}
- Extract: ${meta.tavily.extract?.status ?? '不明'}
`;
}

function renderMarkdown({ meta, report }) {
  if (!report) {
    return renderFailureMarkdown(meta);
  }

  const profile = report.company_profile;

  const recentNewsSection =
    profile.recent_news.length > 0
      ? profile.recent_news.map((n) => `- ${n.summary}${renderSourceRefs(n.source_ids)}`).join('\n')
      : '（出典から裏付けが取れる最近の動きは見つかりませんでした。下記「注意事項」を参照）';

  const orgSignalsSection =
    profile.org_signals.length > 0
      ? profile.org_signals.map((s) => `- ${s.signal}${renderSourceRefs(s.source_ids)}`).join('\n')
      : '（該当情報なし）';

  const hypothesesSection = report.proposal_hypotheses
    .map((h, i) => `${i + 1}. **${h.hypothesis}**${renderSourceRefs(h.evidence_source_ids)}\n   ${h.rationale}`)
    .join('\n');

  const questionsSection = report.discovery_questions.map((q) => `- ${q}`).join('\n');

  const uncertaintiesSection =
    report.uncertainties.length > 0
      ? report.uncertainties.map((u) => `- ${u.note}（理由: ${u.reason}）`).join('\n')
      : '（特になし）';

  const footnotes = report.sources.map((s) => `[^${s.id}]: [${s.title ?? s.url}](${s.url})`).join('\n');

  return `# ${profile.company_name} 商談準備レポート

生成日時: ${meta.generated_at}
調査目的: ${meta.input.research_purpose}
提案する商品・サービス: ${meta.input.offering}

## 企業概要

${profile.business_overview.text}${renderSourceRefs(profile.business_overview.source_ids)}

## 最近の動き

${recentNewsSection}

## 組織シグナル

${orgSignalsSection}

## 導入・提案仮説

${hypothesesSection}

## 商談で確認すべき質問

${questionsSection}

## 注意事項・不足情報

${uncertaintiesSection}

## 出典

${footnotes}
`;
}

const input = $('Fixed Test Input').first().json;
const tavilyOutput = $('Normalize, Dedupe & Structure Output').first().json;
const openAiResponse = $('OpenAI Responses API').first().json;

const result = assembleReport({ input, tavilyOutput, openAiResponse });
const markdown = renderMarkdown(result);

return [{ json: { meta: result.meta, report: result.report, markdown } }];
